var OUT_OF_STOCK = [];
var TOTAL_VALUE = 0;
var CATEGORIES = {};

function go(file) {
  var data = JSON.parse(fs.readFileSync(file, "utf8"));
  for (var i = 0; i < data.length; i++) {
    var item = data[i];
    if (item.qty !== undefined) {
      if (item.price !== undefined) {
        TOTAL_VALUE = TOTAL_VALUE + item.qty * item.price;
