        CATEGORIES[item.category].count = CATEGORIES[item.category].count + 1;
        CATEGORIES[item.category].value = CATEGORIES[item.category].value + item.qty * item.price;
        if (item.qty === 0) {
          OUT_OF_STOCK.push(item.sku);
        } else {
          if (item.qty < 5) {
            LOW.push(item.sku + " (" + item.qty + ")");
          }
        }
      }
    }
  }
}

function print_report() {
  var lines = [];
  lines.push("INVENTORY VALUE: " + TOTAL_VALUE.toFixed(2));
  var cats = Object.keys(CATEGORIES).sort();
  for (var j = 0; j < cats.length; j++) {
    var c = cats[j];
    lines.push(c + ": " + CATEGORIES[c].count + " items, value " + CATEGORIES[c].value.toFixed(2));
  }
  lines.push("LOW STOCK: " + (LOW.length === 0 ? "none" : LOW.join(", ")));
  lines.push("OUT OF STOCK: " + (OUT_OF_STOCK.length === 0 ? "none" : OUT_OF_STOCK.join(", ")));
  console.log(lines.join("\n"));
}

