import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));

// Exact expected stdout of the untouched legacy script for FIXTURE below.
// Captured verbatim from `node inventory.js <fixture>` — do not "fix" it.
const GOLDEN = [
  "INVENTORY VALUE: 234.25",
  "food: 2 items, value 6.75",
  "tools: 2 items, value 199.90",
  "toys: 3 items, value 27.60",
  "LOW STOCK: C3 (3), D4 (2)",
  "OUT OF STOCK: B2",
  "",
].join("\n");

const FIXTURE = [
  { sku: "A1", category: "tools", qty: 10, price: 19.99 },
  { sku: "B2", category: "food", qty: 0, price: 4.5 }, // out of stock
  { sku: "C3", category: "food", qty: 3, price: 2.25 }, // low stock
  { sku: "D4", category: "toys", qty: 2, price: 9.95 }, // low stock
  { sku: "E5", category: "toys", qty: 7, price: 1.1 },
  { sku: "F6", category: "tools", qty: 5, price: undefined }, // missing price -> excluded
  { sku: "G7", category: "toys", qty: undefined, price: 3.33 }, // missing qty -> excluded
];

function makeFixtureFile(dir) {
  const file = path.join(dir, "items.json");
  fs.writeFileSync(file, JSON.stringify(FIXTURE));
  return file;
}

test("legacy inventory.js produces golden output", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "inventory-golden-"));
  const file = makeFixtureFile(dir);
  try {
    const stdout = execFileSync(process.execPath, ["inventory.js", file], {
      cwd: here,
      encoding: "utf8",
    });
    assert.equal(stdout, GOLDEN);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test("bin/report.mjs produces identical output to legacy script", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "inventory-golden-"));
  const file = makeFixtureFile(dir);
  try {
    const legacy = execFileSync(process.execPath, ["inventory.js", file], {
      cwd: here,
      encoding: "utf8",
    });
    const refactored = execFileSync(
      process.execPath,
      [path.join(here, "bin", "report.mjs"), file],
      { cwd: here, encoding: "utf8" }
    );
    assert.equal(refactored, legacy);
    assert.equal(refactored, GOLDEN);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

