          }
        }
      }
    }
  }

  return { totalValue: totalValue, categories: categories, lowStock: lowStock, outOfStock: outOfStock };
}

export function renderReport(result) {
  var lines = [];
  lines.push("INVENTORY VALUE: " + result.totalValue.toFixed(2));
  var cats = Object.keys(result.categories).sort();
  for (var j = 0; j < cats.length; j++) {
