import { test } from "node:test";
import assert from "node:assert/strict";
import { analyze } from "./inventory.mjs";

test("items missing qty or price are excluded from every statistic", () => {
  const result = analyze([
    { sku: "NO-QTY", category: "a", price: 5 },
    { sku: "NO-PRICE", category: "a", qty: 3 },
    { sku: "OK", category: "a", qty: 10, price: 2 },
    { sku: "ZERO", category: "b", qty: 0, price: 1 },
    { sku: "LOW", category: "b", qty: 4, price: 1 },
  ]);
  assert.equal(result.totalValue, 21); // 10*2 + 0*1 + 4*1 only
  assert.deepEqual(result.categories, {
    a: { count: 1, value: 20 },
    b: { count: 2, value: 1 },
  });
  assert.deepEqual(result.lowStock, ["LOW (4)"]);
  assert.deepEqual(result.outOfStock, ["ZERO"]);
});

test("category ordering in report is sorted alphabetically", async () => {
  const { renderReport } = await import("./inventory.mjs");
  const result = analyze([
    { sku: "Z", category: "zebra", qty: 1, price: 1 },
    { sku: "A", category: "apple", qty: 1, price: 1 },
    { sku: "M", category: "mango", qty: 1, price: 1 },
  ]);
  const out = renderReport(result);
  const catLines = out.split("\n").filter((l) => !l.startsWith("INVENTORY") && !l.startsWith("LOW") && !l.startsWith("OUT"));
  assert.deepEqual(catLines.map((l) => l.split(":")[0]), ["apple", "mango", "zebra"]);
});

test("qty 0 item is out-of-stock but NOT low-stock", () => {
  const result = analyze([{ sku: "X1", category: "c", qty: 0, price: 9.99 }]);
  assert.deepEqual(result.outOfStock, ["X1"]);
  assert.deepEqual(result.lowStock, []);
});

